import { renderFlow, TARGETS } from "bitfab-flow";
import { describe, expect, it } from "vitest";
import { assistantFlow } from "./assistant.js";
import { setupFlow } from "./setup.js";
import { updateFlow } from "./update.js";
/**
 * "Gate" is this document's word for a check, not the user's. When it appears
 * in the prose the agent picks it up and hands it over verbatim: "running the
 * Refactor confirmation gate", "your root does not clear the gate" reached a
 * real user.
 *
 * So the word is banned outright in flow prose, in every sense: the named
 * construct ("the Replayability gate"), the verb ("gate the lens on
 * `costRun`"), and the participle ("each flag is gated on the SDK"). A flat
 * ban is a rule that cannot rot the way a clever pattern does.
 *
 * "gate" was only the loudest instance. The list below is every term that
 * names one of OUR constructs as a thing the user runs into: a check their
 * code can fail, or a unit of control flow they are supposedly inside of.
 *
 * Terms deliberately NOT banned, because they are the user's language or
 * ordinary engineering English, not ours: "orchestrator" (their LangChain
 * node), "fan-out" (how the agent parallelizes its own judging), "entry point"
 * (the root of a trace), "chrome", "short-circuit", "no-op", "downstream".
 * Banning those would cost clarity and buy nothing.
 *
 * If you are here because this test failed: do not widen the regex, rename the
 * thing. Say what it is for.
 */
const BANNED_WORDS = [
    // Named checks. Every one has a plain equivalent: requirement, check,
    // depends on, only when.
    /\bgat(?:e|es|ed|ing)\b/gi,
    /\bsafety[- ]nets?\b/gi,
    // Named units of our own control flow, which the user is not inside of.
    /\bInstrument cycle\b/gi,
    /\btails? into\b/gi,
    /\bself-skips?(?:ped)?\b/gi,
];
const FLOWS = [
    ["setup", setupFlow],
    ["assistant", assistantFlow],
    ["update", updateFlow],
];
function leaksIn(flow, targetName) {
    const found = [];
    for (const file of renderFlow(flow, TARGETS[targetName])) {
        for (const line of file.content.split("\n")) {
            for (const pattern of BANNED_WORDS) {
                for (const match of line.matchAll(pattern)) {
                    found.push(`${file.slug || "<root>"}: ...${line.slice(Math.max(0, match.index - 50), match.index + 40).trim()}...`);
                }
            }
        }
    }
    return found;
}
describe("flow prose never says gate", () => {
    for (const [name, flow] of FLOWS) {
        for (const targetName of Object.keys(TARGETS)) {
            it(`${name} (${targetName}) names checks in plain English`, () => {
                expect(leaksIn(flow, targetName)).toEqual([]);
            });
        }
    }
});
/**
 * Branch options are the raw material for an `AskUserQuestion`: the agent
 * copies labels into the prompt more or less verbatim and paraphrases the
 * descriptions. So an option must offer the user a CONCEPT ("adjust what an
 * existing trace captures"), never a location in this document ("jump to the
 * Modify phase", "returns to step 2"), which is what the user would then be
 * asked to choose between.
 *
 * Labels are held to the stricter bar because they survive into the prompt
 * unedited: no structural nouns, and no identifiers or placeholders either.
 */
const LABEL_BANNED = /\b(?:gate|phase|steps?\s*\d|sub-skill|orchestrator|dispatch|invariant|wizard|mode)\b|`[^`]+`|\{\{/i;
const DESCRIPTION_BANNED = /\b(?:the\s+\w+\s+phase|\bphase\s+[A-Z0-9]|steps?\s*\d+|gate)\b/i;
function optionLeaks(flow) {
    const found = [];
    for (const phase of flow.phases) {
        for (const step of phase.steps) {
            if (step.kind !== "branch") {
                continue;
            }
            for (const branch of step.branches) {
                const option = branch.option;
                if (option === undefined) {
                    continue;
                }
                const at = `${phase.id}/${step.id} [${option.letter}]`;
                if (LABEL_BANNED.test(option.label)) {
                    found.push(`${at} label: ${option.label}`);
                }
                if (option.description !== undefined &&
                    DESCRIPTION_BANNED.test(option.description)) {
                    found.push(`${at} description: ${option.description}`);
                }
            }
        }
    }
    return found;
}
describe("AskUserQuestion options offer concepts, not places in the flow", () => {
    for (const [name, flow] of FLOWS) {
        it(`${name} option labels and descriptions name only concepts`, () => {
            expect(optionLeaks(flow)).toEqual([]);
        });
    }
});
/**
 * The sentence that tells the agent to ask must not characterize the
 * interaction in this document's own terms. "This is a gate, not a failure to
 * retry blindly. Then ask with two options:" invites the agent to open the
 * question by calling it a gate.
 *
 * Cross-references stay: "after the instructions from step 14, ask what to do
 * next", or a pointer to a section that really is titled "Phase Benchmark".
 * Those tell the agent where it is, and no agent relays them as part of the
 * question. Only characterizing the interaction as a gate is banned; phase
 * and step names shown to the user are caught by the option audit above.
 */
const ASK_TRIGGER = /\{\{askVerb\}\}|\{\{askNoun\}\}|AskUserQuestion|ask the user/i;
const ASK_BANNED = /\bgate\b/i;
/**
 * Scoped to a single sentence on a single line. A whole-file scan would pair
 * an ask instruction with the word "gate" paragraphs away and report a leak
 * that no agent could possibly utter in one breath.
 */
function askProseLeaks(flow, targetName) {
    const found = [];
    for (const file of renderFlow(flow, TARGETS[targetName])) {
        for (const line of file.content.split("\n")) {
            for (const sentence of line.split(/(?<=\.)\s+/)) {
                if (ASK_TRIGGER.test(sentence) && ASK_BANNED.test(sentence)) {
                    found.push(`${file.slug || "<root>"}: ${sentence.trim().slice(0, 120)}`);
                }
            }
        }
    }
    return found;
}
describe("instructions to ask do not carry internal framing", () => {
    for (const [name, flow] of FLOWS) {
        for (const targetName of Object.keys(TARGETS)) {
            it(`${name} (${targetName}) ask-prose names no gates or phases`, () => {
                expect(askProseLeaks(flow, targetName)).toEqual([]);
            });
        }
    }
});
